import 'package:dharm_guru_shrinkhala/services/astro.dart';
import 'package:flutter_test/flutter_test.dart';

/// Phase 17 reference validation. Every case compares the
/// Dart engine numerically against Skyfield 1.55 with JPL
/// DE421, generated by
/// docs/implementation/generate_reference_cases.py and stored
/// in docs/implementation/reference_cases.json. Full case
/// definitions are in
/// docs/implementation/REFERENCE_VALIDATION_CASES.md.
/// Tolerances: Sun 0.5 degrees, Moon 1.0, planets 2.0,
/// ascendant 1.0.
void main() {
  const List<String> planets = <String>[
    'Sun',
    'Moon',
    'Mercury',
    'Venus',
    'Mars',
    'Jupiter',
    'Saturn',
  ];

  void checkCase(
    String name,
    DateTime utc,
    AstroPlace place,
    Map<String, double> tropical,
    double ascendant,
  ) {
    for (final String planet in planets) {
      final double got = tropicalLongitudeAt(planet: planet, utc: utc);
      final double expected = tropical[planet]!;
      final double tolerance = planet == 'Sun'
          ? 0.5
          : planet == 'Moon'
              ? 1.0
              : 2.0;
      expect(
        (got - expected).abs(),
        lessThan(tolerance),
        reason: '$name $planet expected $expected, got $got',
      );
    }
    final double gotAsc = ascendantTropical(utc: utc, place: place);
    double diff = (gotAsc - ascendant).abs();
    if (diff > 180.0) diff = 360.0 - diff;
    expect(
      diff,
      lessThan(1.0),
      reason: '$name ascendant expected $ascendant, got $gotAsc',
    );
  }

  test('canonical 1998-03-14 Jaipur', () {
    checkCase(
      'canonical',
      DateTime.utc(1998, 3, 14, 0, 55),
      kDefaultPlace,
      <String, double>{
        'Sun': 353.2684,
        'Moon': 182.4691,
        'Mercury': 9.8575,
        'Venus': 307.6117,
        'Mars': 7.2565,
        'Jupiter': 339.0346,
        'Saturn': 19.6025,
      },
      347.4588,
    );
  });

  test('leap day 2000-02-29 Delhi', () {
    checkCase(
      'leap_2000',
      DateTime.utc(2000, 2, 29, 6, 30),
      placeFor('Delhi')!,
      <String, double>{
        'Sun': 339.9773,
        'Moon': 272.83,
        'Mercury': 342.7375,
        'Venus': 313.675,
        'Mars': 13.0508,
        'Jupiter': 32.5354,
        'Saturn': 42.3487,
      },
      77.4741,
    );
  });

  test('leap day near midnight 2024-02-29 Mumbai', () {
    checkCase(
      'leap_2024_midnight',
      DateTime.utc(2024, 2, 29, 18, 29),
      placeFor('Mumbai')!,
      <String, double>{
        'Sun': 340.3225,
        'Moon': 217.3586,
        'Mercury': 341.5535,
        'Venus': 315.8722,
        'Mars': 312.4028,
        'Jupiter': 40.9387,
        'Saturn': 339.5487,
      },
      234.7306,
    );
  });

  test('southern hemisphere 2005-06-15 Sydney', () {
    const AstroPlace sydney = AstroPlace('Sydney', -33.8688, 151.2093);
    checkCase(
      'sydney_south',
      DateTime.utc(2005, 6, 14, 22, 30),
      sydney,
      <String, double>{
        'Sun': 83.8701,
        'Moon': 172.5243,
        'Mercury': 97.3023,
        'Venus': 103.7279,
        'Mars': 1.8931,
        'Jupiter': 188.9953,
        'Saturn': 116.0094,
      },
      104.5164,
    );
  });

  test('DST fall back first hour 2010-11-07 New York', () {
    const AstroPlace york = AstroPlace('New York', 40.7128, -74.0060);
    checkCase(
      'newyork_dst_first',
      DateTime.utc(2010, 11, 7, 5, 30),
      york,
      <String, double>{
        'Sun': 224.5426,
        'Moon': 238.116,
        'Mercury': 237.1953,
        'Venus': 210.2389,
        'Mars': 247.0216,
        'Jupiter': 353.5656,
        'Saturn': 192.0214,
      },
      152.178,
    );
  });

  test('DST fall back second hour 2010-11-07 New York', () {
    const AstroPlace york = AstroPlace('New York', 40.7128, -74.0060);
    checkCase(
      'newyork_dst_second',
      DateTime.utc(2010, 11, 7, 6, 30),
      york,
      <String, double>{
        'Sun': 224.5845,
        'Moon': 238.7009,
        'Mercury': 237.2583,
        'Venus': 210.22,
        'Mars': 247.0519,
        'Jupiter': 353.5639,
        'Saturn': 192.026,
      },
      164.0277,
    );
    // The two 01:30 births are different charts: the Moon
    // moves 0.58 degrees and the ascendant 11.85 degrees
    // in the hour between them.
    final double firstAsc = ascendantTropical(
      utc: DateTime.utc(2010, 11, 7, 5, 30),
      place: york,
    );
    final double secondAsc = ascendantTropical(
      utc: DateTime.utc(2010, 11, 7, 6, 30),
      place: york,
    );
    expect((secondAsc - firstAsc).abs(), closeTo(11.85, 1.0));
  });

  test('BST start 2026-03-29 London', () {
    const AstroPlace london = AstroPlace('London', 51.5074, -0.1278);
    checkCase(
      'london_bst',
      DateTime.utc(2026, 3, 29, 1, 30),
      london,
      <String, double>{
        'Sun': 8.0061,
        'Moon': 139.6012,
        'Mercury': 341.094,
        'Venus': 27.6537,
        'Mars': 350.45,
        'Jupiter': 105.2336,
        'Saturn': 4.8133,
      },
      266.2456,
    );
  });

  test('midnight birth 2015-01-01 Kolkata', () {
    checkCase(
      'midnight_kolkata',
      DateTime.utc(2014, 12, 31, 18, 30),
      placeFor('Kolkata')!,
      <String, double>{
        'Sun': 279.7861,
        'Moon': 47.3763,
        'Mercury': 293.0812,
        'Venus': 296.2239,
        'Mars': 320.6606,
        'Jupiter': 141.5647,
        'Saturn': 240.6322,
      },
      194.7139,
    );
  });

  test('Jupiter retrograde 2025-12-01 Jaipur', () {
    checkCase(
      'jupiter_retrograde',
      DateTime.utc(2025, 12, 1, 12),
      kDefaultPlace,
      <String, double>{
        'Sun': 249.1833,
        'Moon': 20.3202,
        'Mercury': 230.6109,
        'Venus': 240.4633,
        'Mars': 259.3025,
        'Jupiter': 114.1395,
        'Saturn': 354.8044,
      },
      69.8223,
    );
  });

  test('Saturn retrograde 2025-08-01 Jaipur', () {
    checkCase(
      'saturn_retrograde',
      DateTime.utc(2025, 8, 1, 12),
      kDefaultPlace,
      <String, double>{
        'Sun': 129.1424,
        'Moon': 218.8298,
        'Mercury': 128.2735,
        'Venus': 91.1869,
        'Mars': 176.2504,
        'Jupiter': 101.4611,
        'Saturn': 1.2645,
      },
      282.6988,
    );
  });

  test('new moon 2026-12-08 Jaipur', () {
    checkCase(
      'new_moon_dec_2026',
      DateTime.utc(2026, 12, 8, 6, 30),
      kDefaultPlace,
      <String, double>{
        'Sun': 255.7903,
        'Moon': 247.3761,
        'Mercury': 242.5247,
        'Venus': 212.2786,
        'Mars': 154.0897,
        'Jupiter': 146.6085,
        'Saturn': 7.5588,
      },
      333.0397,
    );
  });

  test('full moon 2026-12-23 Jaipur', () {
    checkCase(
      'full_moon_dec_2026',
      DateTime.utc(2026, 12, 23, 6, 30),
      kDefaultPlace,
      <String, double>{
        'Sun': 271.0484,
        'Moon': 79.7636,
        'Mercury': 265.7035,
        'Venus': 224.7016,
        'Mars': 158.0925,
        'Jupiter': 146.4738,
        'Saturn': 7.6893,
      },
      353.1699,
    );
  });

  test('canonical sidereal values match the DE441 table', () {
    // Tropical minus Lahiri ayanamsa must reproduce the
    // JPL Horizons DE441 sidereal values in astro_test.
    final DateTime utc = DateTime.utc(1998, 3, 14, 0, 55);
    final double d = julianDay(utc) - 2451543.5;
    final double ayan = ayanamsa(d);
    double sidereal(String planet) {
      final double tropical =
          tropicalLongitudeAt(planet: planet, utc: utc);
      double value = (tropical - ayan) % 360.0;
      if (value < 0) value += 360.0;
      return value;
    }

    expect(sidereal('Sun'), closeTo(329.44, 0.5));
    expect(sidereal('Moon'), closeTo(158.63, 1.0));
    expect(sidereal('Jupiter'), closeTo(315.21, 2.0));
    expect(sidereal('Saturn'), closeTo(355.78, 2.0));
  });
}
